import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/*eslint-disable*/
import SnackBar from "@/components/SnackBar.vue";
import EditProject from "@/components/TimeSheets/PopUps/EditProject.vue";
import DeleteProject from "@/components/TimeSheets/PopUps/DeleteProject.vue";
import { create_project } from "@/graphql/mutations.js";
import { get_projects } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    DeleteProject,
    EditProject,
    SnackBar
  },
  data() {
    return {
      projectHeaders: [{
        title: "Name",
        key: "project_name",
        sortable: false
      }, {
        title: "Activities",
        key: "project_activities",
        sortable: false
      }, {
        title: "Action",
        key: "actions",
        sortable: false
      }],
      fixed: true,
      activityData: [],
      activityList: [],
      projectName: "",
      SnackBarComponent: {},
      projectitems: {},
      projectDeletion: false,
      projectEdition: false,
      componentCheck: 0,
      loading: false,
      tableHeight: 0,
      tableData: [],
      loadingBtn: false
    };
  },
  async created() {
    this.tableHeight = window.innerHeight - 290;
    "temValue", eventData => {
      this.activityData = [];
      eventData.forEach(element => {
        this.activityData.push({
          title: element.activity_name,
          value: element.activity_name
        });
      });
    };
    await this.fetch_projectes();
  },
  methods: {
    add_mutation() {
      if (this.$refs.form.validate()) {
        this.create_project_with_activities();
      }
    },
    edit_item(item) {
      this.projectitems = item;
      this.componentCheck = 1;
      this.projectEdition = true;
    },
    delete_item(item) {
      this.projectitems = item;
      this.componentCheck = 2;
      this.projectDeletion = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.projectEdition = false;
      this.projectDeletion = false;
      this.fetch_projectes();
    },
    async create_project_with_activities() {
      var data = this.$store.getters.GetUserObj;
      this.loadingBtn = true;
      try {
        let result = await API.graphql(graphqlOperation(create_project, {
          input: {
            project_name: this.projectName,
            // organization_id: data.organization.organization_id,
            project_activities: this.activityList,
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.create_project);
        if (response.Status == "SUCCESS") {
          this.loadingBtn = false;
          this.$refs.form.reset();
          this.fetch_projectes();
        } else {
          this.loadingBtn = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loadingBtn = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async fetch_projectes() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_projects, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        var response = JSON.parse(result.data.get_projects);
        this.tableData = [];
        this.loading = false;
        this.tableData = response.data;
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
